package com.alsafa.native4;

import android.app.Activity;import android.view.Gravity;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.EditText;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.AccountingChoices;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;
/** Repair entry: agreed amount/currency are independent from collection destination. */
public final class CoreRepairPanelBinder {
 private final Activity a;private final Native4Services services;private final TextView status;private final EditText customer,watch,total;private final Spinner currency,account;
 public CoreRepairPanelBinder(Activity a,Native4Services services,TextView status){if(services==null)throw new IllegalArgumentException("Native4Services مطلوب");this.a=a;this.services=services;this.status=status;customer=a.findViewById(R.id.repairCustomer);watch=a.findViewById(R.id.repairWatch);total=a.findViewById(R.id.repairTotal);currency=a.findViewById(R.id.repairCurrency);account=a.findViewById(R.id.repairAccount);currency.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));account.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"الدرج","شام كاش","الخزنة الخارجية","البنك","لاحق / غير مقبوض"}));prepare(customer);prepare(watch);prepare(total);Button save=a.findViewById(R.id.saveRepair);save.setText("حفظ الصيانة");save.setMinHeight(dp(64));save.setTextSize(18);save.setOnClickListener(v->save());}
 private void prepare(EditText e){e.setGravity(Gravity.END);e.setMinHeight(dp(56));e.setPadding(dp(14),dp(8),dp(14),dp(8));}
 private void save(){try{String c=customer.getText().toString().trim(),w=watch.getText().toString().trim();if(c.isEmpty())throw new IllegalArgumentException("اسم العميل مطلوب");if(w.isEmpty())throw new IllegalArgumentException("وصف الساعة أو الصيانة مطلوب");String amountText=total.getText().toString().trim();if(amountText.isEmpty())throw new IllegalArgumentException("قيمة الصيانة المتفق عليها مطلوبة");double amount=Double.parseDouble(amountText);if(amount<0)throw new IllegalArgumentException("قيمة الصيانة غير صحيحة");String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,currency.getSelectedItemPosition()),pay=paymentCode(account.getSelectedItemPosition());if("SHAM_CASH".equals(pay)&&"TRY".equals(cur))throw new IllegalArgumentException("شام كاش يقبل الدولار والليرة السورية فقط");String id=services.repairs.receive(c,"",w,amount,cur,pay);Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();customer.setText("");watch.setText("");total.setText("");account.setSelection(0);status.setText("✓ تم حفظ الصيانة — المتفق عليه: "+amount+" "+cur+" — "+accountLabel(pay)+" — المرجع: "+id);}catch(Exception e){status.setText("لم تُحفظ الصيانة: "+msg(e));}}
 private static String paymentCode(int p){if(p==1)return "SHAM_CASH";if(p==2)return "EXTERNAL";if(p==3)return "BANK";if(p==4)return "LATER";return "CASH";}private static String accountLabel(String p){if("SHAM_CASH".equals(p))return "شام كاش";if("EXTERNAL".equals(p))return "الخزنة الخارجية";if("BANK".equals(p))return "البنك";if("LATER".equals(p))return "غير مقبوض";return "الدرج";}
 private int dp(int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}
